[CmdletBinding()]param([Parameter(Mandatory=$true)][string]$Path)
$ErrorActionPreference='Stop';$x=Get-Content (Join-Path $Path 'project-story.json') -Raw|ConvertFrom-Json;if($x.offer.status -ne 'closed' -or $x.offer.actual_cost -gt $x.offer.planned_cost){throw 'STORY_BUDGET_OR_OFFER_INVALID'};if(@($x.pages).Count -lt 2 -or $x.pages[1].parent -ne $x.pages[0].id){throw 'STORY_PAGE_PARENT_INVALID'};foreach($t in @($x.tickets)){if($t.status -in @('done','closed') -and (@($t.acceptance).Count -eq 0 -or @($t.evidence).Count -eq 0 -or @($t.comments).Count -eq 0)){throw 'STORY_TICKET_CLOSURE_GATE_FAILED'}};if(@($x.timeline).Count -ne 13){throw 'STORY_TIMELINE_INCOMPLETE'};foreach($e in @($x.evidence)){if([string]$e.hash -notmatch '^[a-f0-9]{64}$'){throw 'STORY_EVIDENCE_HASH_INVALID'}};foreach($h in @($x.hypercare)){if($h.priority -eq 'P1' -and $h.status -ne 'closed'){throw 'STORY_OPEN_P1_AT_HYPERCARE_END'}};if(@($x.hypercare|? status -ne 'closed').Count -gt 0){throw 'STORY_HYPERCARE_INCOMPLETE'};Write-Host 'PASS: Synthetic project story, ticket closure, timeline and hypercare validate.'
